INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 31, 'theory', 'Quiz: runtimes and tests');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 0, 'What does "secure by default" mean in Deno?', '["Code is encrypted at startup", "A program has no access to files, network or environment until permissions are granted with flags", "Deno does not run other people''s code", "All permissions are granted, but logged"]', 1, 'Without --allow-* flags a script cannot read files, use the network or read environment variables.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 1, 'What do Node, Deno and Bun have in common that makes code portable?', '["The same engine", "A set of web standards: fetch, Request/Response, URL, Web Streams, AbortController", "A shared package manager", "An identical file system"]', 1, 'Web-standard APIs exist in all runtimes. Platform features (files, processes) are best hidden behind an adapter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 2, 'How do you run Node''s built-in tests?', '["node --test", "npm install mocha", "node run tests", "node --jest"]', 0, 'The node:test module and the node --test command need no third-party libraries.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 3, 'What are fake timers for?', '["To speed up the processor", "To test time-dependent code (debounce, retries, timeouts) without real waiting", "To disable setTimeout for good", "To measure memory"]', 1, 'The test advances time by hand (tick/advance), and all timers fire instantly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 4, 'Why can''t the result of the first benchmark run be taken as representative?', '["The first run is always faster", "The engine has not optimized the code yet: you need warm-up and repetitions, and the report should show the median", "The first run doesn''t count", "The timer is not on yet"]', 1, 'JIT compilation and caches make the first measurements slower. You need warm-up, many repetitions and robust statistics (median, spread).');
